SELECT status, CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END AS opened_cohort, DATE_TRUNC('MONTH', opened_date) AS opened_month, ROUND(STDDEV(balance), 2) AS stddev_balance, COUNT(balance) AS balance_count FROM accounts WHERE status IS NOT NULL AND customer_id IN (30, 31, 34) GROUP BY status, CASE WHEN YEAR(opened_date) < 2024 THEN 'before_2024' WHEN YEAR(opened_date) = 2024 THEN '2024' ELSE 'after_2024' END, DATE_TRUNC('MONTH', opened_date) ORDER BY status DESC, opened_cohort, opened_month LIMIT 10;
